IF DB_ID('Part2Check') IS NOT NULL BEGIN ALTER DATABASE Part2Check SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE Part2Check; END
CREATE DATABASE Part2Check;
GO
USE Part2Check;
CREATE TABLE Customers (CustomerId INT IDENTITY PRIMARY KEY, CustomerName NVARCHAR(200) NOT NULL, Email NVARCHAR(320) NOT NULL UNIQUE, CreatedAt DATETIME2 NOT NULL);
CREATE TABLE Products (ProductId INT IDENTITY PRIMARY KEY, ProductName NVARCHAR(200) NOT NULL, Price DECIMAL(18,2) NOT NULL, StockQuantity INT NOT NULL, IsActive BIT NOT NULL);
CREATE TABLE Orders (OrderId BIGINT IDENTITY PRIMARY KEY, CustomerId INT NOT NULL REFERENCES Customers(CustomerId), OrderStatus VARCHAR(30) NOT NULL, TotalAmount DECIMAL(18,2) NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL);
CREATE TABLE OrderItems (OrderItemId BIGINT IDENTITY PRIMARY KEY, OrderId BIGINT NOT NULL REFERENCES Orders(OrderId), ProductId INT NOT NULL REFERENCES Products(ProductId), Quantity INT NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL);
SET IDENTITY_INSERT Customers ON; INSERT Customers (CustomerId, CustomerName, Email, CreatedAt) VALUES (101, N'Test', N't@example.com', SYSUTCDATETIME()); SET IDENTITY_INSERT Customers OFF;
SET IDENTITY_INSERT Products ON; INSERT Products (ProductId, ProductName, Price, StockQuantity, IsActive) VALUES (1001, N'A', 150.00, 3, 1), (1002, N'B', 99.50, 1, 1); SET IDENTITY_INSERT Products OFF;
